INSERT INTO reviews (id, store_id, product_id, author, role, text, rating, is_published, created_at) VALUES
  ('50070000-0000-4000-8000-000000000001', '50010000-0000-4000-8000-000000000001', '50030000-0000-4000-8000-000000000001', 'Sofia M.', 'Cliente fidèle', 'Un sillage qui rappelle un jardin après la pluie. Livraison rapide et emballage soigné.', 5, true, '2026-11-18T09:37:28.300Z'),
  ('50070000-0000-4000-8000-000000000002', '50010000-0000-4000-8000-000000000001', '50030000-0000-4000-8000-000000000001', 'Amara O.', 'Acheteur vérifié', 'L’Oud Nocturne tient toute la soirée. On m’a demandé le nom trois fois.', 5, true, '2026-11-14T09:37:28.300Z'),
  ('50070000-0000-4000-8000-000000000003', '50010000-0000-4000-8000-000000000001', '50030000-0000-4000-8000-000000000002', 'Nadia T.', 'Acheteur vérifié', 'Rose de Mai est devenue mon parfum du quotidien, léger sans être fade.', 5, true, '2026-11-10T09:37:28.300Z'),
  ('50070000-0000-4000-8000-000000000004', '50010000-0000-4000-8000-000000000001', '50030000-0000-4000-8000-000000000005', 'Clarisse E.', 'Acheteur vérifié', 'Santal Velours est doux et enveloppant, exactement ce que je cherchais.', 4, true, '2026-11-06T09:37:28.300Z'),
  ('50070000-0000-4000-8000-000000000005', '50010000-0000-4000-8000-000000000001', '50030000-0000-4000-8000-000000000004', 'Jean-Paul K.', 'Client', 'Bon parfum mais la tenue est un peu courte à mon goût.', 3, false, '2026-11-02T09:37:28.300Z'),
  ('50070000-0000-4000-8000-000000000006', '50010000-0000-4000-8000-000000000001', '50030000-0000-4000-8000-000000000003', 'Lydie B.', 'Cadeau', 'Réponse immédiate sur WhatsApp et conseils précis pour choisir mon cadeau.', 5, false, '2026-10-29T09:37:28.300Z');
